#!/usr/bin/env node

const { spawn } = require("child_process");

// remove first two args (node path + script path)
const args = process.argv.slice(2);

if (args.length === 0) {
  console.log("No query provided.");
  process.exit(0);
}

// join words with +
const query = args.join("+");

// build URL
const url = `https://duckduckgo.com/?ia=web&q=${query}`;

// run librewolf
spawn("librewolf", [url], {
  detached: true,
  stdio: "ignore"
}).unref();

