#!/usr/bin/env node

// ====== CONFIG ======
const FILE_PATH = "/home/matthew/confusing-excellence/Mental Buffer.md";
// ====================

const fs = require("fs");

// process.argv[0] = node
// process.argv[1] = script path
// everything after that = user arguments
const args = process.argv.slice(2);

// Join all words into one line
const textToAppend = args.join(" ");

if (!textToAppend) {
  console.log("No text provided.");
  process.exit(0);
}

try {
  fs.appendFileSync(FILE_PATH, "\n- " + textToAppend, "utf8");
  console.log("Appended successfully.");
} catch (err) {
  console.error("Error writing to file:", err.message);
}

